"""Return a list object representation of the output from cflow

    Example:
    If cflow_output is:
    main() <int () at main.c:18>:
        f() <int () at main.c:4>:
            malloc()
            printf()

    Then this function will return:
    ['main() <int () at main.c:18>:',
    ['f() <int () at main.c:4>:', ['malloc()', 'printf()']]]

    Parameters:
    cflow_output: string
    """
def get_list_representation(cflow_output: Any) -> object {
    import from tokenize { NEWLINE, INDENT, DEDENT, tokenize }
    import io;
    stack = [[]];
    lastindent = len(stack);
    def push_new_list() -> object {
        stack[-1].append([]);
        stack.append(stack[-1][-1]);
        return len(stack);
    }
    readl = io.BytesIO(cflow_output.encode('utf-8')).readline;
    for t in tokenize(readl) {
        if (t.type == NEWLINE) {
            if (lastindent != len(stack)) {
                stack.pop();
                lastindent = push_new_list();
            }
            stack[-1].append(t.line.strip());
        } elif (t.type == INDENT) {
            lastindent = push_new_list();
        } elif (t.type == DEDENT) {
            stack.pop();
        }
    }
    return stack[-1];
}

"""Convert d-m-y to y-m-d where original data recorded day in year format
    """
def dash_to_slash(datetime_str: str) -> str {
    (date, time) = datetime_str.split();
    date_arr = date.split('-');
    if (len(date_arr[0]) > 2) {
        date_arr[0] = date_arr[0][-2:];
    }
    date_str = '/'.join(date_arr);
    ret_string = date_str + ' ' + time;
    return ret_string;
}

"""
    sort
    :param arr:
    :return:
    """
def sort(arr: Any) -> object {
    l = len(arr);
    for i in range(0, l) {
        for j in range((i + 1), l) {
            if (arr[i] >= arr[j]) {
                tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
            }
        }
    }
    return arr;
}

